llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C67"],
      "claim": "Propranolol, a basic secondary-amine aryloxypropanolamine with moderate lipophilicity, has an absolute oral bioavailability of 29% in humans, above the 20% threshold despite extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Encainide, which contains a methoxy-substituted aromatic ring and a basic amine, shows an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20% for a similar basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C74"],
      "claim": "Verapamil, a lipophilic basic amine with multiple methoxyphenyl groups, has an absolute oral bioavailability of 22.0% in normal subjects, just above the 20% threshold despite substantial first-pass extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Metoprolol, a basic aryloxypropanolamine beta-blocker, has a mean systemic availability of 50 ± 11% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C78"],
      "claim": "Diphenhydramine, a lipophilic basic benzhydryl ether, has an absolute oral bioavailability of 72% in humans, supporting high oral bioavailability for a basic amine with low TPSA.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Metoclopramide, a basic substituted benzamide, has a mean absolute oral bioavailability of 86.6 ± 4.7%, demonstrating that basic amine drugs with aromatic substituents can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C96"],
      "claim": "In 20 normal young men, verapamil oral bioavailability averaged 19.4% after single oral doses compared with intravenous dosing, a sub-20% value; however, this is dose/study-dependent and outweighed by multiple verapamil and analogue values above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic basic secondary amine with low TPSA and moderate logD. Multiple high-transfer analogues with similar basic-amine and aromatic features—propranolol, encainide, verapamil, metoprolol, diphenhydramine, and metoclopramide—show absolute oral bioavailability mostly between 22% and 86%, all at or above the 20% threshold. Occasional sub-20% verapamil values are dose-dependent and do not overturn the consistent high-F direction. Therefore the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for the query molecule.",
    "First-pass metabolism and transporter involvement for the query are unknown.",
    "The very low neutral fraction at pH 7.4 may reduce passive permeability, but analogue evidence indicates this alone is insufficient to predict low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

